begin;
create function pg_temp.ok(v boolean,label text)returns void language plpgsql as $$begin if v is not true then raise exception 'FAIL: %',label;end if;perform set_config('folio.workflow_checks',(coalesce(nullif(current_setting('folio.workflow_checks',true),''),'0')::int+1)::text,true);end$$;
create function pg_temp.no(statement text,label text)returns void language plpgsql as $$begin begin execute statement;exception when others then perform pg_temp.ok(true,label);return;end;raise exception 'FAIL: % accepted',label;end$$;
with u as(insert into auth.users(id,email,email_confirmed_at)values(gen_random_uuid(),'workflows-a@example.invalid',now())returning id)select set_config('folio.wa',id::text,true)from u;
with u as(insert into auth.users(id,email,email_confirmed_at)values(gen_random_uuid(),'workflows-b@example.invalid',now())returning id)select set_config('folio.wb',id::text,true)from u;
select set_config('folio.wmonth',date_trunc('month',folio_private.today()-interval '1 month')::date::text,true);
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.wa'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.wa'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
update public.profiles set tracking_start_date=null where id=current_setting('folio.wa')::uuid;
with a as(insert into public.accounts(name,type,opening_balance_paise,opening_date)values('Synthetic from','bank',100000,(current_setting('folio.wmonth'))::date)returning id)select set_config('folio.wfrom',id::text,true)from a;
with a as(insert into public.accounts(name,type,opening_balance_paise,opening_date)values('Synthetic to','bank',0,(current_setting('folio.wmonth'))::date)returning id)select set_config('folio.wto',id::text,true)from a;
select set_config('folio.wcat',(select id::text from public.categories where kind='expense'limit 1),true);
select set_config('folio.wentry',public.record_entry(current_setting('folio.wfrom')::uuid,current_setting('folio.wcat')::uuid,'expense',10029,(current_setting('folio.wmonth'))::date,'Synthetic expense',null,gen_random_uuid())::text,true);
select pg_temp.ok((select count(*)>=1 from public.audit_events where table_name='transactions'),'ledger writes audited');
select pg_temp.no('delete from public.audit_events','audit cannot be deleted by client');
select set_config('folio.wspec',jsonb_build_object('from_account',current_setting('folio.wfrom'),'to_account',current_setting('folio.wto'),'amount_paise',25000,'debit_on',current_setting('folio.wmonth'),'credit_on',((current_setting('folio.wmonth'))::date+1)::text,'description','Synthetic own transfer','debit_source',jsonb_build_object('sha',repeat('a',64),'row','1:3'),'credit_source',jsonb_build_object('sha',repeat('b',64),'row','1:4'),'existing_transfer',null)::text,true);
select pg_temp.ok(public.preview_transfer_match(current_setting('folio.wspec')::jsonb)->'matches'='[]'::jsonb,'new pair preview does not post');
select pg_temp.ok((select count(*)=1 from public.transactions),'preview is read-only');
select set_config('folio.wreq',gen_random_uuid()::text,true);
select set_config('folio.wtransfer',public.confirm_transfer_match(current_setting('folio.wspec')::jsonb,current_setting('folio.wreq')::uuid)::text,true);
select pg_temp.ok(public.confirm_transfer_match(current_setting('folio.wspec')::jsonb,current_setting('folio.wreq')::uuid)::text=current_setting('folio.wtransfer'),'transfer retry idempotent');
select pg_temp.ok((select count(*)=3 from public.transactions),'only two transfer legs posted');
select pg_temp.ok((public.preview_transfer_match(current_setting('folio.wspec')::jsonb)->>'already_linked')::boolean,'both source markers saved');
select pg_temp.no(format('select public.confirm_transfer_match(%L,gen_random_uuid())',current_setting('folio.wspec')),'existing pair cannot be posted again');
select pg_temp.ok(public.confirm_transfer_match(jsonb_set(current_setting('folio.wspec')::jsonb,'{existing_transfer}',to_jsonb(current_setting('folio.wtransfer'))),gen_random_uuid())::text=current_setting('folio.wtransfer'),'existing transfer can be explicitly linked');
select pg_temp.ok((select sum(amount_paise)=-10029 from public.transactions),'transfers do not become spending/income');
select pg_temp.ok(not(public.account_statement_report(current_setting('folio.wfrom')::uuid,date_trunc('month',folio_private.today())::date)->>'complete_month')::boolean,'current month cannot close before the next month begins');
select set_config('folio.wreport',public.account_statement_report(current_setting('folio.wfrom')::uuid,current_setting('folio.wmonth')::date)::text,true);
select pg_temp.ok(current_setting('folio.wreport')::jsonb->>'closing_paise'='64971','closing balance includes transfer debit');
select pg_temp.no(format('select public.reconcile_account(%L,%L,100000,64970,%L)',current_setting('folio.wfrom'),current_setting('folio.wmonth'),current_setting('folio.wreport')::jsonb->>'ledger_hash'),'one-paise mismatch cannot reconcile');
select public.reconcile_account(current_setting('folio.wfrom')::uuid,current_setting('folio.wmonth')::date,100000,64971,current_setting('folio.wreport')::jsonb->>'ledger_hash');
select set_config('folio.wto_report',public.account_statement_report(current_setting('folio.wto')::uuid,current_setting('folio.wmonth')::date)::text,true);
select public.reconcile_account(current_setting('folio.wto')::uuid,current_setting('folio.wmonth')::date,0,25000,current_setting('folio.wto_report')::jsonb->>'ledger_hash');
select set_config('folio.wmonth_report',public.monthly_review_report(current_setting('folio.wmonth')::date)::text,true);
select pg_temp.ok(current_setting('folio.wmonth_report')::jsonb->>'expenses_paise'='10029','monthly spend excludes transfers');
select public.review_month(current_setting('folio.wmonth')::date,current_setting('folio.wmonth_report')::jsonb->>'report_hash');
select pg_temp.ok((public.monthly_review_report(current_setting('folio.wmonth')::date)->'review'->>'current')::boolean,'month marked reviewed');
select public.record_entry(current_setting('folio.wfrom')::uuid,current_setting('folio.wcat')::uuid,'expense',10030,current_setting('folio.wmonth')::date,'Changed synthetic expense',current_setting('folio.wentry')::uuid,gen_random_uuid());
select pg_temp.ok(not(public.monthly_review_report(current_setting('folio.wmonth')::date)->'review'->>'current')::boolean,'later edits invalidate reviewed month');
select pg_temp.ok(not(public.account_statement_report(current_setting('folio.wfrom')::uuid,current_setting('folio.wmonth')::date)->'review'->>'current')::boolean,'later edits invalidate statement review');
select public.save_planning(jsonb_build_object('salary_day',1,'salary_account_id',current_setting('folio.wfrom'),'spending_account_id',current_setting('folio.wfrom'),'loan_funding','{}'::jsonb));
select public.save_planned_event(null,jsonb_build_object('name','Synthetic planned bill','kind','expense','account_id',current_setting('folio.wfrom'),'to_account_id',null,'amount_paise',1000,'due_on',folio_private.today()+5,'cadence','monthly','within_budget',true,'active',true));
select pg_temp.ok((select count(*)=3 from public.transactions),'plans do not post money');
select set_config('folio.wloan',public.save_loan_document(null,0,jsonb_build_object('name','Synthetic archive loan','provider','credit_saison','source_sha256',repeat('c',64),'source_page_count',1,'original_principal_paise',1200000,'original_months',12,'nominal_rate',0,'disclosure_apr',3.25,'net_disbursed_paise',null,'fees_paise',null,'reported_emi_paise',100000,'current_outstanding_paise',600000,'remaining_months',6,'as_of',folio_private.today(),'paid_through',null,'first_due_on',null,'balance_basis','manual','card_account_id',null,'schedule_origin','none','schedule','[]'::jsonb,'source_pages',jsonb_build_object('principal',1,'rate',1,'apr',1,'emi',1,'tenure',1,'first_due',null)),gen_random_uuid())::text,true);
select public.save_debt_terms(current_setting('folio.wloan')::uuid,null,jsonb_build_object('prepayment_percent',2,'closure_fee_paise',1000,'tax_percent',18,'promo_apr',0,'promo_until',folio_private.today()+60));
select public.save_planning(jsonb_build_object('salary_day',1,'salary_account_id',current_setting('folio.wfrom'),'spending_account_id',current_setting('folio.wfrom'),'loan_funding',jsonb_build_object(current_setting('folio.wloan'),current_setting('folio.wfrom'))));
select set_config('folio.wholding',public.save_investment_holding(null,0,'{"name":"Synthetic archive investment","scheme":"ppf","provider":"Fixture","funding_source":"self","locked_until":null,"account_id":null,"archived":false}',2000029,folio_private.today()-1,gen_random_uuid())::text,true);
select public.record_investment_entry(current_setting('folio.wholding')::uuid,1,null,'employer',10029,folio_private.today(),'Synthetic employer contribution',false,gen_random_uuid());
select pg_temp.ok(jsonb_array_length(public.investment_return_history(current_setting('folio.wholding')::uuid))=2,'full investment return history is owned and complete');
select set_config('folio.warchive',public.export_financial_data()::text,true);
select pg_temp.ok(current_setting('folio.warchive')::jsonb->>'schema_version'='2','new exports use restore-capable version');
select pg_temp.ok(jsonb_array_length(current_setting('folio.warchive')::jsonb->'source_markers'->'statement_rows')=2,'source duplicate markers exported');
select pg_temp.ok(not(public.preview_financial_restore(current_setting('folio.warchive')::jsonb)->>'can_restore')::boolean,'restore refuses nonempty target');
select set_config('request.jwt.claim.sub',current_setting('folio.wb'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.wb'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
select pg_temp.ok((select count(*)=0 from public.audit_events where user_id=current_setting('folio.wa')::uuid),'audit owner isolation');
select pg_temp.no(format('select public.account_statement_report(%L,%L)',current_setting('folio.wfrom'),current_setting('folio.wmonth')),'other owner account inaccessible');
select pg_temp.no(format('select public.save_debt_terms(%L,null,''{"prepayment_percent":0,"closure_fee_paise":0,"tax_percent":0,"promo_apr":null,"promo_until":null}''::jsonb)',current_setting('folio.wloan')),'other owner lender terms denied');
select pg_temp.no(format('select public.investment_return_history(%L)',current_setting('folio.wholding')),'other owner investment history denied');
select pg_temp.no(format('select public.preview_transfer_match(%L)',current_setting('folio.wspec')),'other owner transfer accounts denied');
select pg_temp.no(format('select public.preview_financial_restore(%L)',jsonb_set(current_setting('folio.warchive')::jsonb,'{data,accounts,0,user_id}',to_jsonb(current_setting('folio.wb')))::text),'mixed archive ownership denied');
select pg_temp.no(format('select public.preview_financial_restore(%L)',jsonb_set(current_setting('folio.warchive')::jsonb,'{data,accounts,0,unknown}', 'true')::text),'unknown archive fields denied');
select pg_temp.no(format('select public.preview_financial_restore(%L)',jsonb_set(current_setting('folio.warchive')::jsonb,'{data,transactions,1,amount_paise}', '"999"')::text),'unbalanced archive transfer rolls back');
select pg_temp.ok((select count(*)=0 from public.accounts),'invalid archives leave no partial records');
select pg_temp.no(format('select public.preview_financial_restore(%L)',jsonb_set(current_setting('folio.warchive')::jsonb,'{data,investment_entries,0,occurred_on}',to_jsonb((folio_private.today()+1)::text))::text),'future investment activity denied');
select pg_temp.no(format('select public.preview_financial_restore(%L)',jsonb_set(current_setting('folio.warchive')::jsonb,'{source_markers,statement_rows,0,source_sha256}', '"invalid"')::text),'invalid source marker denied');
select set_config('folio.wlegacy',(jsonb_set(current_setting('folio.warchive')::jsonb-'source_markers','{schema_version}','1')||jsonb_build_object('data',(current_setting('folio.warchive')::jsonb->'data')-array['account_reconciliations','month_reviews','planning_settings','planned_cash_events','debt_terms','audit_events']))::text,true);
select pg_temp.ok((public.preview_financial_restore(current_setting('folio.wlegacy')::jsonb)->>'legacy_source_warning')::boolean,'version-one archive validates with missing-source warning');
select set_config('folio.wpreview',public.preview_financial_restore(current_setting('folio.warchive')::jsonb)::text,true);
select pg_temp.ok((current_setting('folio.wpreview')::jsonb->>'can_restore')::boolean,'complete archive previews in empty target');
select pg_temp.ok((select count(*)=0 from public.accounts),'restore preview rolled back all financial rows');
select pg_temp.no(format('select public.confirm_financial_restore(%L,''wrong'',''RESTORE INTO EMPTY WORKSPACE'',gen_random_uuid())',current_setting('folio.warchive')),'changed archive hash denied');
select set_config('folio.wrestore_req',gen_random_uuid()::text,true);
select public.confirm_financial_restore(current_setting('folio.warchive')::jsonb,current_setting('folio.wpreview')::jsonb->>'archive_hash','RESTORE INTO EMPTY WORKSPACE',current_setting('folio.wrestore_req')::uuid);
select pg_temp.ok((select count(*)=2 from public.accounts),'accounts restored under new identifiers');
select pg_temp.ok((select count(*)=1 from public.loan_document_details d join public.loans l on l.id=d.loan_id and l.user_id=d.user_id),'loan documents remapped to restored loans');
select pg_temp.ok((select count(*)=1 from public.debt_terms d join public.loans l on l.id=d.loan_id and l.user_id=d.user_id),'lender terms remapped to restored loans');
select pg_temp.ok((select count(*)=2 from public.investment_entries),'investment cash-flow history restored');
select pg_temp.ok((select count(*)=1 from public.planning_settings p,jsonb_each_text(p.loan_funding)e join public.loans l on l.id=e.key::uuid),'nested forecast references remapped');
select pg_temp.ok(not exists(select 1 from public.accounts where id=current_setting('folio.wfrom')::uuid),'archive identifiers are remapped');
select pg_temp.ok((select count(*)=3 and sum(amount_paise)=-10030 from public.transactions),'restored accounting totals exact');
select pg_temp.ok((public.confirm_financial_restore(current_setting('folio.warchive')::jsonb,current_setting('folio.wpreview')::jsonb->>'archive_hash','RESTORE INTO EMPTY WORKSPACE',current_setting('folio.wrestore_req')::uuid)->>'restored')::boolean,'restore retry is idempotent');
select pg_temp.no(format('select public.confirm_financial_restore(%L,%L,''RESTORE INTO EMPTY WORKSPACE'',gen_random_uuid())',current_setting('folio.warchive'),current_setting('folio.wpreview')::jsonb->>'archive_hash'),'second restore cannot duplicate records');
select pg_temp.ok((select count(*)>0 from public.audit_events where provenance='archive'),'prior audit labelled imported');
select pg_temp.ok((select count(*)=1 from public.audit_events where action='RESTORE'and provenance='live'),'restore itself audited by server');
reset role;
select pg_temp.ok((select count(*)=2 from folio_private.statement_rows where user_id=current_setting('folio.wb')::uuid),'duplicate source markers remapped to new owner');
select current_setting('folio.workflow_checks')||' workflow assertions passed';
rollback;
